use crate::model::*; use std::{path::Path,process::Command}; use thiserror::Error;
#[derive(Error,Debug)] pub enum ReadError { #[error("{0}")] Io(String), #[error("command failed: {0}")] Command(String), #[error("invalid JSON: {0}")] Json(String) }
pub fn roster(scripts:&Path,root:&Path)->Result<Vec<RosterEntry>,ReadError>{let o=Command::new(scripts.join("roster")).current_dir(root).output().map_err(|e|ReadError::Io(e.to_string()))?; if !o.status.success(){return Err(ReadError::Command(String::from_utf8_lossy(&o.stderr).into()))} Ok(String::from_utf8_lossy(&o.stdout).lines().filter_map(|l|{let p:Vec<_>=l.split_whitespace().collect();if p.len()<3{None}else{Some(RosterEntry{name:p[0].into(),role:p[1].into(),kind:if p[2]=="implementer"{AgentKind::Implementer}else{AgentKind::Interactive}})}}).collect())}
pub fn beads(root:&Path)->Result<Vec<Bead>,ReadError>{let o=Command::new("bd").args(["--readonly","-C"]).arg(root).args(["list","--status","open,in_progress,blocked,deferred,closed","--json","--brief"]).output().map_err(|e|ReadError::Io(e.to_string()))?;if !o.status.success(){return Err(ReadError::Command(String::from_utf8_lossy(&o.stderr).into()))}serde_json::from_slice(&o.stdout).map_err(|e|ReadError::Json(e.to_string()))}
pub fn process_scan()->Result<Vec<ProcessRow>,ReadError>{let o=Command::new("ps").args(["-axo","pid=,ppid=,args="]).output().map_err(|e|ReadError::Io(e.to_string()))?;if !o.status.success(){return Err(ReadError::Command(String::from_utf8_lossy(&o.stderr).into()))}crate::model::parse_processes(&String::from_utf8_lossy(&o.stdout)).map_err(ReadError::Command)}
